import {uid,esc} from './core.js';import {timeline,validateContext,freezeBundle,compareBundles} from './investigation.js';
export function createInvestigationUI(ui){const {button,showDialog,field,area,selectField}=ui;const bundles=()=>ui.project().investigationBundles?.filter(b=>b.deviceId===ui.project().deviceId)||[];let filter='All';
function view(){const p=ui.project(),rows=timeline(p).filter(r=>filter==='All'||r.evidence.kind===filter);return `<div class="panel-body"><div class="row between wrap"><div><h3>Connected investigation</h3><p class="muted spaced">Evidence across serial, firmware, network and debugger acquisitions.</p></div><div class="row wrap">${button('Freeze evidence bundle','invest-bundle','primary')}${button('Compare bundles','invest-compare','small','',bundles().length<2?'disabled':'')}${button('Filter','invest-filter','small')}</div></div><p class="notice spaced">Times default to preservation/import time. Record collection time, correction and uncertainty explicitly. Nearby timestamps do not establish causation.</p><div class="table-wrap spaced"><table><thead><tr><th>Time / basis</th><th>Evidence</th><th>Firmware / conditions</th><th>Actions</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.time===null?'Unknown':esc(new Date(r.time).toISOString())}<span class="sub">${esc(r.timeBasis)}${r.context?' · ±'+r.context.uncertaintyMs+' ms':''}</span></td><td>${esc(r.evidence.title)}<span class="sub">${esc(r.evidence.kind)}</span></td><td>${esc(r.context?.firmwareHash?.slice(0,12)||'Unlinked')}<span class="sub">${esc(r.context?.conditions||'Not recorded')}</span></td><td>${button('Context','invest-context','small','',`data-id="${r.evidence.id}"`)} ${button('Original','evidence-detail','small','',`data-id="${r.evidence.id}"`)} ${button('Finding','invest-finding','small','',`data-id="${r.evidence.id}"`)}</td></tr>`).join('')||'<tr><td colspan="4">No matching evidence.</td></tr>'}</tbody></table></div><h3 class="spaced">Frozen bundles</h3>${bundles().map(b=>`<div class="baseline-row spaced"><strong>${esc(b.label)}</strong><p>${b.entries.length} originals · ${esc(b.conditions)}</p>${button('Export bundle','invest-export','small','download',`data-id="${b.id}"`)}</div>`).join('')||'<p class="muted spaced">Freeze selected originals and their present context before a retest.</p>'}</div>`;}
function context(id){const p=ui.project(),e=p.evidence.find(e=>e.id===id&&e.deviceId===p.deviceId);if(!e)throw Error('Missing evidence.');const c=(p.investigationContexts||[]).find(c=>c.evidenceId===id)||{observedAt:e.createdAt,offsetMs:0,uncertaintyMs:0,timeBasis:'import',firmwareHash:'',conditions:''};showDialog('Acquisition context',`<div class="form-grid">${field('Observed timestamp (ISO, including time zone)','observedAt',c.observedAt,'text',true)}${selectField('Time basis','timeBasis',['collection','import','unknown'],c.timeBasis)}${field('Add clock correction (milliseconds)','offsetMs',c.offsetMs,'number')}${field('Clock uncertainty ± milliseconds','uncertaintyMs',c.uncertaintyMs,'number')}<label class="field full">Firmware original<select name="firmwareHash"><option value="">Unknown / unlinked</option>${p.artifacts.filter(a=>a.deviceId===e.deviceId).map(a=>`<option value="${a.hash}" ${a.hash===c.firmwareHash?'selected':''}>${esc(a.name)} · ${a.hash.slice(0,12)}</option>`).join('')}</select></label>${area('Vantage point, device state and time source','conditions',c.conditions)}</div><p class="notice spaced">Correction is added to the recorded timestamp; originals are unchanged. Existing frozen bundles retain their earlier annotation.</p>`,d=>{if(ui.project()!==p||p.deviceId!==e.deviceId)throw Error('Device changed.');const n={evidenceId:id,deviceId:e.deviceId,observedAt:d.get('observedAt'),timeBasis:d.get('timeBasis'),offsetMs:Number(d.get('offsetMs')),uncertaintyMs:Number(d.get('uncertaintyMs')),firmwareHash:d.get('firmwareHash'),conditions:d.get('conditions')};validateContext(n);p.investigationContexts??=[];p.investigationContexts=p.investigationContexts.filter(x=>x.evidenceId!==id);p.investigationContexts.push(n);ui.changed('Acquisition context saved.');},'Save context');}
return {view,async action(name,id){if(!name.startsWith('invest-'))return false;const p=ui.project();if(name==='invest-context')context(id);else if(name==='invest-finding')ui.findingDialog('',[id]);else if(name==='invest-filter')showDialog('Filter timeline',selectField('Evidence kind','kind',['All',...new Set(p.evidence.filter(e=>e.deviceId===p.deviceId).map(e=>e.kind))],filter),d=>{filter=d.get('kind');ui.render();},'Apply');else if(name==='invest-bundle'){const deviceId=p.deviceId;showDialog('Freeze evidence bundle',field('Bundle label','label','','text',true)+area('Shared test conditions','conditions','')+ui.evidenceChecks(),d=>{if(ui.project()!==p||p.deviceId!==deviceId)throw Error('Device changed.');p.investigationBundles??=[];if(p.investigationBundles.length>=1000)throw Error('Bundle limit reached.');p.investigationBundles.push(freezeBundle(p,{id:uid('bundle'),label:d.get('label'),conditions:d.get('conditions'),evidenceIds:d.getAll('evidenceIds')}));ui.changed('Bundle frozen with original hashes and context.');},'Freeze bundle');}else if(name==='invest-export'){const b=bundles().find(b=>b.id===id);ui.download('probe-bundle.json',JSON.stringify({format:'probe-investigation-bundle-v1',projectId:p.id,bundle:b,evidence:b.entries.map(x=>p.evidence.find(e=>e.id===x.evidenceId))},null,2));}else if(name==='invest-compare'){const bs=bundles();showDialog('Compare evidence bundles',['before','after'].map((key,i)=>`<label class="field">${key}<select name="${key}">${bs.map((b,j)=>`<option value="${b.id}" ${j===(i?bs.length-1:0)?'selected':''}>${esc(b.label)}</option>`).join('')}</select></label>`).join(''),d=>{const a=bs.find(b=>b.id===d.get('before')),b=bs.find(b=>b.id===d.get('after'));if(a===b)throw Error('Choose different bundles.');const r=compareBundles(a,b);setTimeout(()=>showDialog('Bundle comparison',`<p class="notice">${esc(r.limitation)} ${r.conditionsMatch?'Conditions text matches.':'Conditions text differs.'}</p><div class="table-wrap spaced"><table><tbody>${r.rows.map(x=>`<tr><td>${esc(x.title)}</td><td>${esc(x.detail)}</td></tr>`).join('')}</tbody></table></div>`),0);},'Compare');}return true;}};
}
